pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 seed, uint256 blockNum, uint256 timestamp) public {
        vm.assume(value == 10 ether);
        vm.assume(timestamp > 0);

        // Set block parameters
        vm.warp(timestamp);
        vm.roll(blockNum);

        // Record the contract balance before
        uint256 balanceBefore = address(c).balance;

        // Send exactly 10 ether to trigger fallback
        (bool success, ) = address(c).call{value: value}("");

        // Only consider succeeded calls
        if (success) {
            // The rule: if block.number % 15 != 0 then contract balance should increase by 10 ether
            // If block.number % 15 == 0 then balance should be zero (since transfer sends all)
            if (block.number % 15 == 0) {
                assertTrue(address(c).balance == 0, "Balance should be zero on multiples of 15");
            } else {
                assertTrue(address(c).balance == balanceBefore + 10 ether, "Balance should increase by 10 ether");
            }
        }
    }
}

