pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp1, uint256 timestamp2) public {
        // Bound timestamps to be within reasonable range
        timestamp1 = bound(timestamp1, 1, 2**64);
        timestamp2 = bound(timestamp2, 1, 2**64);

        // Ensure timestamp1 < timestamp2 for the first call to succeed
        vm.assume(timestamp1 < timestamp2);

        // First fallback call: set pastBlockTime to timestamp2
        vm.warp(timestamp2);
        vm.deal(address(this), 10 ether);
        (bool success1,) = address(c).call{value: 10 ether}("");
        assertTrue(success1);

        // Second call with same timestamp as stored pastBlockTime
        // The reference will revert because block.timestamp must be > pastBlockTime
        // The mutant will succeed because block.timestamp >= pastBlockTime
        vm.warp(timestamp2);
        (bool success2,) = address(c).call{value: 10 ether}("");

        // General rule: when msg.value == 10 ether and block.timestamp == pastBlockTime, call must revert
        assertTrue(!success2);
    }
}

