pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp1, uint256 timestamp2) public {
        // Bound timestamp values to reasonable range and ensure increasing
        timestamp1 = bound(timestamp1, 1, 1000000);
        timestamp2 = bound(timestamp2, timestamp1 + 1, timestamp1 + 1000);

        // Set block number such that first call does NOT trigger transfer
        // and second call DOES trigger transfer (block.number % 15 == 0)
        vm.assume(blockNumber % 15 != 0);
        uint256 triggerBlock = blockNumber + (15 - (blockNumber % 15));

        // First call: no transfer
        vm.warp(timestamp1);
        vm.roll(blockNumber);
        deal(address(c), 10 ether);
        vm.deal(address(this), 10 ether);

        (bool success1, ) = address(c).call{value: 10 ether}("");

        // Second call: should trigger transfer
        vm.warp(timestamp2);
        vm.roll(triggerBlock);

        uint256 balanceBefore = address(this).balance;
        (bool success2, ) = address(c).call{value: 10 ether}("");
        uint256 balanceAfter = address(this).balance;

        // Rule: If second call succeeded and block.number % 15 == 0, then
        // the contract should transfer all its balance to the caller
        assertTrue(!success2 || balanceAfter >= balanceBefore + 10 ether);
    }
}

